// Generated by scripts/bundle-sql.js from db/. Don't edit by hand: run `npm run bundle-sql`.
export default {
 "schema.sql": "create extension if not exists pgcrypto;\n\ncreate table users (\n  id            uuid primary key default gen_random_uuid(),\n  email         text unique,\n  username      citext unique,\n  password_hash text,\n  is_admin      boolean not null default false,\n  admin_role    text not null default 'catalog',\n  banned        boolean not null default false,\n  balance_cents bigint  not null default 0,\n  xp            int     not null default 0,\n  streak        int     not null default 0,\n  last_bet_at   timestamptz,\n  last_bonus_at timestamptz,\n  created_at    timestamptz not null default now()\n);\n\ncreate table sessions (\n  token_hash text primary key,\n  user_id    uuid not null references users(id) on delete cascade,\n  expires_at timestamptz not null,\n  created_at timestamptz not null default now()\n);\n\ncreate table magic_links (\n  token_hash text primary key,\n  user_id    uuid not null references users(id) on delete cascade,\n  expires_at timestamptz not null,\n  used_at    timestamptz\n);\n\ncreate table deposit_addresses (\n  address text primary key,\n  user_id uuid not null references users(id) on delete cascade,\n  idx     int  not null unique,\n  created_at timestamptz not null default now()\n);\n\ncreate table ledger (\n  id         bigserial primary key,\n  user_id    uuid not null references users(id) on delete cascade,\n  delta_cents bigint not null,\n  kind       text not null,           -- deposit|withdraw|order|bet|payout|bonus|adjust\n  ref        text,\n  meta       jsonb not null default '{}',\n  created_at timestamptz not null default now()\n);\ncreate index on ledger (user_id, created_at desc);\n\ncreate table withdrawals (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references users(id) on delete cascade,\n  amount_cents bigint not null,\n  address    text not null,\n  status     text not null default 'pending',  -- pending|sent|rejected\n  tx_hash    text,\n  created_at timestamptz not null default now(),\n  handled_at timestamptz\n);\n\ncreate table product_groups (\n  id          uuid primary key default gen_random_uuid(),\n  slug        text unique not null,\n  name        text not null,\n  description text not null default '',\n  logo_url    text,\n  country     text not null default 'WW',   -- ISO-2 or 'WW' for worldwide\n  category    text not null default 'Other',\n  tags        text[] not null default '{}',\n  wallet_address text,\n  wallet_pk_enc  text,\n  sort        int not null default 0,\n  active      boolean not null default true,\n  created_at  timestamptz not null default now()\n);\n\ncreate table products (\n  id         uuid primary key default gen_random_uuid(),\n  group_id   uuid not null references product_groups(id) on delete cascade,\n  name       text not null,\n  price_cents bigint not null check (price_cents >= 0),\n  stock      int,\n  delivery   text not null default '',   -- text delivered on purchase\n  sort       int not null default 0,\n  active     boolean not null default true,\n  created_at timestamptz not null default now()\n);\ncreate index on products (group_id, price_cents);\n\ncreate table orders (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references users(id) on delete cascade,\n  group_id   uuid references product_groups(id) on delete set null,\n  product_id uuid references products(id) on delete set null,\n  price_cents bigint not null,\n  status     text not null default 'paid',   -- paid|delivered|refunded\n  delivery   text not null default '',\n  created_at timestamptz not null default now()\n);\n\ncreate table support_tickets (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid references users(id) on delete set null,\n  name       text not null,\n  contact    text not null,\n  subject    text not null,\n  body       text not null,\n  status     text not null default 'open',   -- open|closed\n  created_at timestamptz not null default now()\n);\n\ncreate table support_messages (\n  id        bigserial primary key,\n  ticket_id uuid not null references support_tickets(id) on delete cascade,\n  from_admin boolean not null default false,\n  body      text not null,\n  created_at timestamptz not null default now()\n);\n\ncreate table game_rounds (\n  id        uuid primary key default gen_random_uuid(),\n  user_id   uuid not null references users(id) on delete cascade,\n  game      text not null,\n  stake_cents bigint not null,\n  multiplier numeric(10,2) not null default 2,\n  win_chance numeric(6,4) not null,\n  outcome   numeric(10,2),           -- crash point or null\n  win       boolean,\n  payout_cents bigint not null default 0,\n  pick      text,\n  started_at timestamptz not null default now(),\n  settled_at timestamptz\n);\ncreate index on game_rounds (user_id, started_at desc);\n\ncreate table house_state (\n  id smallint primary key default 1,\n  wallet_address text,\n  balance_cents bigint not null default 0,\n  tau numeric not null default 6.0,\n  edge numeric not null default 0.985,\n  max_chance numeric not null default 0.4925,\n  min_chance numeric not null default 0.02,\n  max_multiplier numeric not null default 100,\n  max_stake_pct numeric not null default 0.25,\n  enabled boolean not null default true,\n  updated_at timestamptz not null default now(),\n  constraint house_singleton check (id = 1)\n);\ninsert into house_state (id) values (1) on conflict do nothing;\n\ncreate table house_ledger (\n  id bigserial primary key,\n  delta_cents bigint not null,\n  kind text not null,\n  ref text,\n  created_at timestamptz not null default now()\n);\n\ncreate table seen_deposits (\n  tx_hash text primary key,\n  user_id uuid not null references users(id) on delete cascade,\n  amount_wei numeric not null,\n  credited_cents bigint not null,\n  created_at timestamptz not null default now()\n);\n\ncreate table settings (\n  key text primary key,\n  value text not null\n);\n\ncreate table admin_audit (\n  id bigserial primary key,\n  user_id uuid references users(id) on delete set null,\n  action text not null,\n  detail jsonb not null default '{}',\n  created_at timestamptz not null default now()\n);",
 "migrations/002_btc.sql": "alter table house_state add column if not exists balance_sats bigint not null default 0;\nalter table house_state drop column if exists balance_cents;\nalter table house_ledger add column if not exists delta_sats bigint not null default 0;\n\nalter table withdrawals add column if not exists amount_sats bigint not null default 0;\nalter table withdrawals add column if not exists fee_sats bigint not null default 0;\n\ndrop table if exists seen_deposits;\ncreate table seen_deposits (\n  tx_key  text primary key,          -- \"<txid>:<deposit address>\"\n  user_id uuid not null references users(id) on delete cascade,\n  sats    bigint not null,\n  credited_cents bigint not null,\n  price_usd numeric not null,\n  created_at timestamptz not null default now()\n);\n\ncreate table deposit_claims (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references users(id) on delete cascade,\n  txid text not null,\n  sats bigint not null default 0,\n  method text not null default 'btc',   -- btc | cashapp | paypal\n  note text not null default '',\n  status text not null default 'pending', -- pending | approved | rejected\n  created_at timestamptz not null default now(),\n  handled_at timestamptz\n);\ncreate unique index on deposit_claims (txid) where method = 'btc';",
 "migrations/003_storefront_controls.sql": "alter table product_groups\n  add column if not exists is_gambling boolean not null default false;\n\ncreate table if not exists site_settings (\n  key text primary key,\n  value text not null,\n  updated_at timestamptz not null default now()\n);\n\ninsert into site_settings (key, value)\nvalues ('gambling_enabled', 'false')\non conflict (key) do nothing;\n",
 "migrations/004_catalog_categories.sql": "alter table product_groups\n  add column if not exists category text not null default 'Other';\n",
 "migrations/005_roles_and_fees.sql": "alter table users\n  add column if not exists admin_role text not null default 'catalog';\n\nupdate users\nset admin_role = 'catalog'\nwhere is_admin = true and (admin_role is null or admin_role = 'god');\n\nalter table withdrawals\n  add column if not exists platform_fee_cents bigint not null default 0;\n\nalter table orders\n  add column if not exists platform_fee_cents bigint not null default 0;\n\ncreate table if not exists platform_fees (\n  id bigserial primary key,\n  user_id uuid references users(id) on delete set null,\n  kind text not null,\n  ref text,\n  amount_cents bigint not null,\n  amount_sats bigint not null default 0,\n  created_at timestamptz not null default now()\n);\n",
 "migrations/006_pool_pot.sql": "-- Pool Pot: equal-stake social pools, one provably-fair winner, disclosed fee,\n-- optional HOUSE seat that is always labelled.\n--\n-- Additive only. Nothing existing is altered except two nullable/limit columns\n-- on users. Reverse with the block at the bottom of this file.\n\ncreate table if not exists pool_tables (\n  id             uuid primary key default gen_random_uuid(),\n  code           text unique not null,                 -- share code, e.g. NEON7\n  name           text not null,\n  stake_cents    bigint not null check (stake_cents > 0),\n  max_seats      int not null check (max_seats between 2 and 12),\n  min_players    int not null default 2 check (min_players >= 2),  -- humans needed to start the clock\n  countdown_secs int not null default 45 check (countdown_secs between 5 and 600),\n  mode           text not null default 'classic' check (mode in ('classic','lightning')),\n  house_seat     boolean not null default false,       -- HOUSE buys a labelled seat each round\n  is_private     boolean not null default false,       -- crew tables: link-only, never in lobby\n  created_by     uuid references users(id) on delete set null,\n  active         boolean not null default true,\n  sort           int not null default 0,\n  created_at     timestamptz not null default now(),\n  check (min_players <= max_seats)\n);\n\ncreate table if not exists pool_rounds (\n  id                uuid primary key default gen_random_uuid(),\n  table_id          uuid not null references pool_tables(id) on delete cascade,\n  seq               int  not null,\n  status            text not null default 'open'\n                    check (status in ('open','countdown','settled','cancelled')),\n  -- snapshot of the ticket when the round opened; admin edits never change a live round\n  stake_cents       bigint not null,\n  max_seats         int    not null,\n  min_players       int    not null,\n  countdown_secs    int    not null,\n  fee_bps           int    not null check (fee_bps between 0 and 5000),\n  house_seat        boolean not null,\n  -- commit-reveal: hash is public from the start, seed is revealed at settle\n  server_seed       text not null,\n  server_seed_hash  text not null,\n  client_seed       text,\n  draw_hash         text,\n  winner_index      int,\n  winner_seat_id    uuid,\n  pot_cents         bigint not null default 0,\n  fee_cents         bigint not null default 0,\n  payout_cents      bigint not null default 0,\n  countdown_ends_at timestamptz,\n  created_at        timestamptz not null default now(),\n  settled_at        timestamptz,\n  unique (table_id, seq)\n);\n-- at most one live round per table\ncreate unique index if not exists pool_rounds_one_live\n  on pool_rounds (table_id) where status in ('open','countdown');\ncreate index if not exists pool_rounds_due\n  on pool_rounds (countdown_ends_at) where status = 'countdown';\ncreate index if not exists pool_rounds_recent on pool_rounds (settled_at desc) where status = 'settled';\n\ncreate table if not exists pool_seats (\n  id          uuid primary key default gen_random_uuid(),\n  round_id    uuid not null references pool_rounds(id) on delete cascade,\n  seat_index  int  not null,\n  user_id     uuid references users(id) on delete set null,\n  is_house    boolean not null default false,\n  client_seed text not null,\n  stake_cents bigint not null,\n  joined_at   timestamptz not null default now(),\n  unique (round_id, seat_index),\n  check (is_house or user_id is not null)\n);\ncreate unique index if not exists pool_seats_one_per_user on pool_seats (round_id, user_id) where user_id is not null;\ncreate unique index if not exists pool_seats_one_house   on pool_seats (round_id) where is_house;\n\n-- The HOUSE seat is not a user, so its money lives here, in cents.\n-- kind: buyin (-stake) | payout (+winnings) | refund (+stake on cancel)\ncreate table if not exists pool_house_ledger (\n  id          bigserial primary key,\n  round_id    uuid references pool_rounds(id) on delete set null,\n  delta_cents bigint not null,\n  kind        text not null,\n  created_at  timestamptz not null default now()\n);\n\n-- Responsible-play controls (self-set; lowering is instant, raising waits 24h)\nalter table users add column if not exists pool_cooloff_until     timestamptz;\nalter table users add column if not exists pool_daily_limit_cents bigint;\nalter table users add column if not exists pool_limit_changed_at  timestamptz;\n\ninsert into site_settings (key, value) values\n  ('pool_enabled',          'false'),\n  ('pool_paused',           'false'),\n  ('pool_fee_bps',          '1000'),\n  ('pool_house_seats',      'true'),\n  ('pool_max_stake_cents',  '10000'),\n  ('pool_crew_tables',      'true')\non conflict (key) do nothing;\n\ninsert into pool_tables (code, name, stake_cents, max_seats, min_players, countdown_secs, mode, house_seat, sort) values\n  ('ZAP4',  'Lightning',   500,  4, 2, 20, 'lightning', false, 0),\n  ('NEON7', 'Neon Table', 1000, 10, 2, 45, 'classic',   true,  1),\n  ('VELVT', 'Velvet',     2500,  6, 2, 45, 'classic',   false, 2),\n  ('APEX5', 'Apex',       5000,  8, 2, 60, 'classic',   true,  3)\non conflict (code) do nothing;\n\n-- ── reverse ────────────────────────────────────────────────────────────────\n-- Refund any live seats first (Admin → Pool → cancel live rounds), then:\n--   drop table pool_house_ledger, pool_seats, pool_rounds, pool_tables;\n--   alter table users drop column pool_cooloff_until,\n--     drop column pool_daily_limit_cents, drop column pool_limit_changed_at;\n--   delete from site_settings where key like 'pool_%';\n",
 "migrations/007_test_mode.sql": "-- Test mode: an account flagged test_mode plays with fake money. Everything it\n-- does is fenced off from real money:\n--   * no deposit address, no on-chain withdrawals (withdrawals are simulated)\n--   * shop orders are marked is_test and never reveal real delivery content\n--   * Pool Pot seats go to a private sandbox copy of the table, filled by\n--     simulated players; real players never see or join a sandbox table\n--   * admin stats and the Pool books check exclude test accounts\n--\n-- Also switches gambling and Pool Pot on (owner request).\n\nalter table users add column if not exists test_mode boolean not null default false;\n\nalter table orders add column if not exists is_test boolean not null default false;\n\nalter table pool_tables add column if not exists is_sandbox boolean not null default false;\nalter table pool_tables add column if not exists sandbox_of uuid references pool_tables(id) on delete cascade;\ncreate unique index if not exists pool_tables_one_sandbox\n  on pool_tables (created_by, sandbox_of) where is_sandbox and sandbox_of is not null;\n\nalter table pool_seats add column if not exists bot_name text;\nalter table pool_seats drop constraint if exists pool_seats_check;\nalter table pool_seats drop constraint if exists pool_seats_who;\nalter table pool_seats add constraint pool_seats_who check (is_house or user_id is not null or bot_name is not null);\n\n-- Pre-existing bug: 002 added house_ledger.delta_sats but left delta_cents NOT NULL\n-- with no default, so every houseMove() insert failed (house balance never moved).\nalter table house_ledger alter column delta_cents set default 0;\n\ninsert into site_settings (key, value) values ('gambling_enabled', 'true')\n  on conflict (key) do update set value = 'true', updated_at = now();\ninsert into site_settings (key, value) values ('pool_enabled', 'true')\n  on conflict (key) do update set value = 'true', updated_at = now();\n\n-- reverse:\n--   alter table pool_seats drop constraint pool_seats_who;\n--   alter table pool_seats add constraint pool_seats_check check (is_house or user_id is not null);  -- after deleting bot seats\n--   alter table pool_seats drop column bot_name;\n--   alter table pool_tables drop column sandbox_of, drop column is_sandbox;\n--   alter table orders drop column is_test;  alter table users drop column test_mode;\n",
 "migrations/008_casino.sql": "-- Casino host platform: third-party game providers talk to Kohler through the\n-- seamless wallet API (/api/casino/v1/...). Money stays in the existing ledger.\n\n-- One row per game provider / aggregator. secret_enc is the shared HMAC key,\n-- sealed with KEY_ENC (AES-256-GCM), never stored in plain text.\ncreate table if not exists casino_providers (\n  id          text primary key,                 -- e.g. 'kohler-studio', 'softswiss'\n  name        text not null,\n  secret_enc  text not null,\n  launch_url  text,                             -- aggregator game-launch endpoint (external providers)\n  active      boolean not null default true,\n  created_at  timestamptz not null default now(),\n  rotated_at  timestamptz\n);\n\ncreate table if not exists casino_games (\n  id            text primary key,               -- provider's game id\n  provider_id   text not null references casino_providers(id),\n  name          text not null,\n  category      text not null check (category in ('slots','live','table','originals')),\n  engine        text not null,                  -- slot | roulette | blackjack | dice | plinko | wheel | external\n  theme         jsonb not null default '{}',\n  rtp           numeric(5,2),                   -- disclosed return to player, %\n  volatility    text,\n  min_bet_cents bigint not null default 10,\n  max_bet_cents bigint not null default 10000,\n  tags          text[] not null default '{}',\n  active        boolean not null default true,\n  sort          int not null default 0,\n  created_at    timestamptz not null default now()\n);\n\n-- A game session is created when a player opens a game. The token goes to the\n-- provider in the launch URL; we only store its hash.\ncreate table if not exists casino_sessions (\n  token_hash  text primary key,\n  user_id     uuid not null references users(id) on delete cascade,\n  game_id     text not null references casino_games(id),\n  provider_id text not null references casino_providers(id),\n  currency    text not null default 'USD',\n  created_at  timestamptz not null default now(),\n  last_seen   timestamptz not null default now(),\n  expires_at  timestamptz not null\n);\ncreate index if not exists casino_sessions_user on casino_sessions (user_id, created_at desc);\n\n-- Every wallet call, exactly once. (provider_id, transaction_id) is the\n-- idempotency key: a retried call returns the original result instead of\n-- moving money twice.\ncreate table if not exists casino_transactions (\n  id                 bigserial primary key,\n  provider_id        text not null references casino_providers(id),\n  transaction_id     text not null,\n  kind               text not null check (kind in ('bet','win','rollback')),\n  user_id            uuid not null references users(id) on delete cascade,\n  game_id            text not null,\n  round_id           text not null,\n  amount_cents       bigint not null check (amount_cents >= 0),\n  balance_after      bigint not null,\n  ref_transaction_id text,                       -- rollback: the bet it cancels\n  request_hash       text not null,              -- detects a reused id with different content\n  status             text not null default 'ok' check (status in ('ok','rolled_back','tombstone')),\n  is_test            boolean not null default false,\n  created_at         timestamptz not null default now(),\n  unique (provider_id, transaction_id)\n);\ncreate index if not exists casino_tx_round on casino_transactions (provider_id, round_id);\ncreate index if not exists casino_tx_user on casino_transactions (user_id, created_at desc);\ncreate index if not exists casino_tx_ref on casino_transactions (provider_id, ref_transaction_id) where ref_transaction_id is not null;\n\n-- Provider-side state for multi-step games (blackjack). In a real deployment\n-- this lives on the provider's servers; Kohler Studio keeps it here.\ncreate table if not exists studio_rounds (\n  id         text primary key,\n  user_id    uuid,\n  game_id    text not null,\n  state      jsonb not null,\n  status     text not null default 'open',\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n",
 "migrations/009_survivor_vault_payouts.sql": "-- Survivor (replaces Pool Pot's winner-takes-most), the Vault (cosmetics) and\n-- automatic payouts. Applied automatically when the server starts.\n\n-- ── Survivor ───────────────────────────────────────────────────────────────\n-- Every live Pool Pot round was played under the old rules: refund all seats first.\nwith live as (select id from pool_rounds where status in ('open','countdown')),\n     owed as (select user_id, round_id, stake_cents from pool_seats where round_id in (select id from live) and user_id is not null)\ninsert into ledger (user_id, delta_cents, kind, ref, meta)\nselect user_id, stake_cents, 'pool_refund', round_id::text, '{\"reason\":\"Survivor upgrade\"}' from owed;\nupdate users u set balance_cents = u.balance_cents + x.s\n  from (select user_id, sum(stake_cents) s from pool_seats\n         where round_id in (select id from pool_rounds where status in ('open','countdown')) and user_id is not null group by user_id) x\n where u.id = x.user_id;\ninsert into pool_house_ledger (round_id, delta_cents, kind)\nselect s.round_id, s.stake_cents, 'refund' from pool_seats s join pool_rounds r on r.id = s.round_id\n join pool_tables t on t.id = r.table_id where r.status in ('open','countdown') and s.is_house and not t.is_sandbox;\nupdate pool_rounds set status = 'cancelled', settled_at = now() where status in ('open','countdown');\n\nalter table pool_tables drop constraint if exists pool_tables_mode_check;\nalter table pool_tables add constraint pool_tables_mode_check check (mode in ('duel','classic','squad','blitz','lightning','crew'));\nalter table pool_tables add column if not exists losers int not null default 1 check (losers >= 1);\nalter table pool_tables add column if not exists house_fill boolean not null default true;\nalter table pool_rounds add column if not exists losers_n int not null default 1;\nalter table pool_rounds add column if not exists loser_indexes int[];\nalter table pool_rounds add column if not exists share_cents bigint not null default 0;\nalter table pool_rounds add column if not exists last_join_at timestamptz;\nalter table pool_rounds add column if not exists loser_names text[];\nalter table pool_rounds add column if not exists loser_seat_ids uuid[];\nalter table pool_seats add column if not exists label text;          -- 'Kohler' for house seats\ndrop index if exists pool_seats_one_house;                           -- tables may carry up to 2 house seats now\n\n-- old tables retire; existing crew tables keep going under Survivor rules\nupdate pool_tables set active = false where code in ('ZAP4','NEON7','VELVT','APEX5');\nupdate pool_tables set mode = 'crew', min_players = max_seats, losers = case when max_seats >= 10 then 2 else 1 end, house_seat = false\n where is_private;\n\ninsert into pool_tables (code, name, stake_cents, max_seats, min_players, countdown_secs, mode, losers, house_seat, house_fill, sort) values\n  ('DUEL5',  'Duel',      500,   2,  2, 30, 'duel',    1, false, false, 0),\n  ('DUEL25', 'Duel',     2500,   2,  2, 30, 'duel',    1, false, false, 1),\n  ('DUEL100','Duel',    10000,   2,  2, 30, 'duel',    1, false, false, 2),\n  ('CLS1',   'Classic',   100,   3,  3, 30, 'classic', 1, false, false, 3),\n  ('CLS5',   'Classic',   500,   3,  3, 30, 'classic', 1, false, false, 4),\n  ('CLS20',  'Classic',  2000,   3,  3, 30, 'classic', 1, false, false, 5),\n  ('SQD10',  'Squad',    1000,   5,  5, 30, 'squad',   1, false, true,  6),\n  ('SQD50',  'Squad',    5000,   5,  5, 30, 'squad',   1, false, true,  7),\n  ('BLZ1',   'Blitz',     100,  10, 10, 30, 'blitz',   2, false, true,  8),\n  ('BLZ5',   'Blitz',     500,  10, 10, 30, 'blitz',   2, false, true,  9)\non conflict (code) do nothing;\n\ninsert into site_settings (key, value) values\n  ('survivor_house_fill', 'true'),          -- Kohler seats top up slow tables\n  ('survivor_house_after_secs', '30'),      -- …after this long without a new player\n  ('survivor_house_max', '2'),              -- at most this many Kohler seats per table\n  ('survivor_house_min_table', '5'),        -- only on tables this big or bigger\n  ('payouts_auto', 'false'),                -- automatic BTC payouts start OFF\n  ('payouts_max_cents', '20000'),           -- auto-pay only withdrawals up to $200\n  ('payouts_daily_cents', '100000'),        -- and at most $1,000 per 24h in total\n  ('payouts_min_age_hours', '24'),          -- account must be this old\n  ('payouts_require_deposit', 'true')       -- and must have made a real deposit\non conflict (key) do nothing;\n\n-- ── Vault (cosmetics) ──────────────────────────────────────────────────────\ncreate table if not exists user_items (\n  user_id     uuid not null references users(id) on delete cascade,\n  item_id     text not null,\n  price_cents bigint not null default 0,\n  is_test     boolean not null default false,\n  acquired_at timestamptz not null default now(),\n  primary key (user_id, item_id)\n);\nalter table users add column if not exists equip jsonb not null default '{}';\nalter table users add column if not exists pass_until timestamptz;\n\n-- ── payouts ────────────────────────────────────────────────────────────────\nalter table withdrawals add column if not exists auto boolean not null default false;\nalter table withdrawals add column if not exists note text;\n",
 "migrations/010_order_contact.sql": "-- How to reach the buyer about an order (prefilled with their email at checkout), and anything\n-- they told us that's needed to deliver it.\nalter table orders add column if not exists contact text;\nalter table orders add column if not exists note text;\n",
 "migrations/011_avatars.sql": "-- Kohler Avatar Factory: AI-painted avatars. Starter avatars are generated on the free\n-- Cloudflare allowance; custom avatars are bought by players and generated on their own budget.\n\ncreate table if not exists avatars (\n  id          uuid primary key default gen_random_uuid(),\n  collection  text not null default 'starter' check (collection in ('starter', 'custom')),\n  owner_id    uuid references users(id) on delete cascade,          -- custom avatars only\n  order_id    uuid,\n  name        text not null,\n  status      text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),\n  tier        text not null default 'free' check (tier in ('free', 'common', 'rare', 'epic', 'legendary', 'custom')),\n  price_cents integer not null default 0 check (price_cents >= 0),\n  category    text, subject text, personality text, accessory text, background text, extra text,\n  prompt      text not null,\n  seed        bigint,\n  provider    text, model text,\n  sha256      text, phash text,\n  width       integer, height integer, bytes integer,\n  sort        integer not null default 0,\n  created_at  timestamptz not null default now(),\n  approved_at timestamptz\n);\ncreate index if not exists avatars_status on avatars (collection, status, sort, created_at);\ncreate index if not exists avatars_owner on avatars (owner_id) where owner_id is not null;\ncreate unique index if not exists avatars_sha on avatars (sha256) where sha256 is not null;\n\ncreate table if not exists avatar_files (\n  avatar_id uuid not null references avatars(id) on delete cascade,\n  size      text not null check (size in ('orig', '512', '128')),\n  mime      text not null,\n  data      bytea not null,\n  primary key (avatar_id, size)\n);\n\ncreate table if not exists avatar_orders (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references users(id) on delete cascade,\n  price_cents integer not null,\n  images      integer not null,\n  spec        jsonb not null,\n  status      text not null default 'generating' check (status in ('generating', 'ready', 'refunded')),\n  refunded_cents integer not null default 0,\n  is_test     boolean not null default false,\n  created_at  timestamptz not null default now(),\n  done_at     timestamptz\n);\ncreate index if not exists avatar_orders_user on avatar_orders (user_id, created_at desc);\n\ncreate table if not exists avatar_jobs (\n  id         uuid primary key default gen_random_uuid(),\n  kind       text not null check (kind in ('catalogue', 'custom')),\n  order_id   uuid references avatar_orders(id) on delete cascade,\n  user_id    uuid references users(id) on delete cascade,\n  spec       jsonb not null,\n  status     text not null default 'queued' check (status in ('queued', 'running', 'done', 'failed', 'cancelled')),\n  attempts   integer not null default 0,\n  last_error text,\n  next_at    timestamptz not null default now(),\n  avatar_id  uuid references avatars(id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index if not exists avatar_jobs_queue on avatar_jobs (status, next_at);\n\n-- images generated per day, per provider and per kind, so the free allowance is never overrun\ncreate table if not exists avatar_usage (\n  day      date not null,\n  provider text not null,\n  kind     text not null,\n  images   integer not null default 0,\n  neurons  integer not null default 0,\n  primary key (day, provider, kind)\n);\n\n-- a job left \"running\" by a crash goes back to the queue on the next start\nupdate avatar_jobs set status = 'queued' where status = 'running';\n\ninsert into site_settings (key, value) values\n  ('avatars_target', '100'),\n  ('avatars_daily_images', '150'),\n  ('avatars_auto_approve', 'false'),\n  ('avatars_paused', 'false'),\n  ('avatars_custom_enabled', 'true'),\n  ('avatars_custom_price_cents', '499'),\n  ('avatars_custom_images', '4')\non conflict (key) do nothing;\n",
 "migrations/012_avatar_retry.sql": "-- Starter avatars that failed because the painter sent a \"seed\" FLUX doesn't accept go back in the\n-- queue (that was our bug, not the images'). Custom orders that failed were already refunded.\nupdate avatar_jobs set status = 'queued', attempts = 0, next_at = now(), last_error = null, updated_at = now()\n where kind = 'catalogue' and status in ('failed', 'queued') and last_error like '%/seed%';\ndelete from site_settings where key in ('avatars_state_error_catalogue', 'avatars_state_error_custom') and value like '%/seed%';\n",
 "migrations/013_security.sql": "-- Security: rate limits shared by every server instance, admin two-factor sign-in,\n-- and when a password last changed (fresh changes hold automatic payouts).\ncreate table if not exists rate_limits (\n  key      text primary key,\n  n        integer not null default 0,\n  reset_at timestamptz not null\n);\ncreate index if not exists rate_limits_reset on rate_limits (reset_at);\n\nalter table users add column if not exists totp_enabled boolean not null default false;\nalter table users add column if not exists totp_secret_enc text;\nalter table users add column if not exists totp_pending_enc text;\nalter table users add column if not exists totp_last_step bigint;\nalter table users add column if not exists password_changed_at timestamptz;\n\nalter table sessions add column if not exists mfa_at timestamptz;\ncreate index if not exists sessions_user on sessions (user_id);\n",
 "migrations/014_avatar_starters.sql": "-- The starter collection now comes from your own list of 100 characters (lib/avatars/style.js,\n-- STARTER). Starter jobs that never produced a picture are dropped and replanned from that list,\n-- and any stored \"painter refused\" state is cleared so painting retries straight away.\ndelete from avatar_jobs where kind = 'catalogue' and status in ('queued', 'failed');\ndelete from site_settings where key like 'avatars\\_state\\_%';\ninsert into site_settings (key, value) values ('avatars_backup_next_at', '') on conflict (key) do nothing;\n",
 "migrations/015_promos.sql": "-- First-deposit bonus and referrals (lib/promos.js).\nalter table users add column if not exists bonus_locked_cents bigint not null default 0;\nalter table users add column if not exists wager_left_cents bigint not null default 0;\nalter table users add column if not exists ref_code text;\nalter table users add column if not exists referred_by uuid references users(id) on delete set null;\nalter table users add column if not exists ref_active_at timestamptz;\ncreate unique index if not exists users_ref_code on users (ref_code) where ref_code is not null;\ncreate index if not exists users_referred_by on users (referred_by) where referred_by is not null;\n\ncreate table if not exists referral_rewards (\n  id           bigserial primary key,\n  user_id      uuid not null references users(id) on delete cascade,\n  milestone    integer not null,          -- 1 = first 10 active referrals, 2 = 20, …\n  active_count integer not null,\n  amount_cents integer not null,\n  created_at   timestamptz not null default now(),\n  unique (user_id, milestone)\n);\n\ninsert into site_settings (key, value) values\n  ('promo_first_enabled', 'true'), ('promo_first_match_pct', '100'), ('promo_first_cap_cents', '5000'), ('promo_wager_x', '5'),\n  ('ref_enabled', 'true'), ('ref_every', '10'), ('ref_reward_cents', '1000'), ('ref_min_deposit_cents', '1000')\non conflict (key) do nothing;\n",
 "migrations/016_streaks_badges.sql": "-- Daily play streaks, XP from every bet, and achievement badges (lib/achievements.js).\nalter table users add column if not exists last_play_day date;\nalter table users add column if not exists best_streak integer not null default 0;\nalter table users add column if not exists xp_bank_cents integer not null default 0;\nalter table users add column if not exists badges text[] not null default '{}';\n\ncreate table if not exists user_badges (\n  user_id   uuid not null references users(id) on delete cascade,\n  badge_id  text not null,\n  earned_at timestamptz not null default now(),\n  seen      boolean not null default false,\n  primary key (user_id, badge_id)\n);\n",
 "migrations/017_promo_campaigns.sql": "-- Promos you can add, edit and switch off from Kohler Control (lib/promos.js).\n-- Replaces the fixed first-deposit / referral settings with a list of promos.\ncreate table if not exists promos (\n  id           bigserial primary key,\n  kind         text not null check (kind in ('deposit_match', 'referral', 'referral_milestone')),\n  name         text not null,\n  enabled      boolean not null default true,\n  config       jsonb not null default '{}',\n  starts_at    timestamptz not null default now(),\n  ends_at      timestamptz,\n  budget_cents bigint,                       -- null = no limit on what this promo can pay out\n  spent_cents  bigint not null default 0,\n  uses         integer not null default 0,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\n-- one row per payment; `key` makes every payment happen at most once\ncreate table if not exists promo_grants (\n  id           bigserial primary key,\n  promo_id     bigint references promos(id) on delete set null,\n  key          text not null unique,\n  user_id      uuid not null references users(id) on delete cascade,\n  role         text not null,               -- player | referrer | friend\n  subject_id   uuid,                        -- the friend, for referral payments\n  amount_cents bigint not null,\n  created_at   timestamptz not null default now()\n);\ncreate index if not exists promo_grants_user on promo_grants (user_id);\ncreate index if not exists promo_grants_promo on promo_grants (promo_id, role);\n\n-- optional: hold referrals made from the referrer's own network (off by default; a switch in Promos)\nalter table users add column if not exists signup_ip_hash text;\nalter table users add column if not exists ref_flag text;\n\n-- carry the old settings over as the first three promos (only on a fresh promos table).\n-- The doubled first deposit starts off: the refer-a-friend bonus replaces it.\ninsert into promos (kind, name, enabled, config)\nselect 'deposit_match', 'First deposit match', false,   -- replaced by the invite bonus; switch it back on in Promos if you want it\n       jsonb_build_object('firstOnly', true, 'pct', s.pct::int, 'cap', s.cap::int, 'minDeposit', 0, 'wagerX', s.wx::int)\n  from (select coalesce((select value from site_settings where key = 'promo_first_enabled'), 'true') fe,\n               coalesce((select value from site_settings where key = 'promo_first_match_pct'), '100') pct,\n               coalesce((select value from site_settings where key = 'promo_first_cap_cents'), '5000') cap,\n               coalesce((select value from site_settings where key = 'promo_wager_x'), '5') wx) s\n where not exists (select 1 from promos)\nunion all\nselect 'referral', 'Refer a friend', true,\n       jsonb_build_object('minDeposit', 2000, 'referrerReward', 1000, 'friendReward', 500, 'friendWager', 10000, 'wagerX', 5, 'maxPerReferrer', 0)\n where not exists (select 1 from promos)\nunion all\nselect 'referral_milestone', 'Every 10 friends', false,\n       jsonb_build_object('every', coalesce((select value from site_settings where key = 'ref_every'), '10')::int,\n                          'reward', coalesce((select value from site_settings where key = 'ref_reward_cents'), '1000')::int, 'wagerX', 5)\n where not exists (select 1 from promos);\n\n-- a friend counts as \"active\" once they've deposited $20 (was $10), unless you'd already changed it\nupdate site_settings set value = '2000' where key = 'ref_min_deposit_cents' and value = '1000';\ninsert into site_settings (key, value) values ('ref_same_network_block', 'false') on conflict (key) do nothing;\n",
 "migrations/018_pending_wins.sql": "-- Game wins the wallet couldn't take at once. Retried until they land (lib/casino/studio.js),\n-- so a win is never lost when a serverless function stops between requests.\ncreate table if not exists studio_pending_wins (\n  transaction_id text primary key,\n  user_id        uuid references users(id) on delete cascade,\n  body           jsonb not null,\n  tries          integer not null default 0,\n  status         text not null default 'pending' check (status in ('pending', 'failed')),\n  last_error     text,\n  next_at        timestamptz not null default now(),\n  created_at     timestamptz not null default now()\n);\ncreate index if not exists studio_pending_wins_due on studio_pending_wins (status, next_at);\ncreate index if not exists studio_pending_wins_user on studio_pending_wins (user_id) where status = 'pending';\n",
 "migrations/019_legends.sql": "-- Legendary avatars: named characters with a personality, painted in the hyperrealistic\n-- surreal style, who also star in games (lib/legends.js). Some epics unlock by playing Survivor.\nalter table avatars drop constraint if exists avatars_collection_check;\nalter table avatars add constraint avatars_collection_check check (collection in ('starter', 'custom', 'legendary'));\n\ncreate table if not exists legends (\n  id            text primary key,                 -- slug, e.g. emperor-bananas\n  name          text not null,\n  title         text not null default '',\n  rarity        text not null default 'common' check (rarity in ('free', 'common', 'rare', 'epic')),\n  emoji         text not null default '⭐',         -- stand-in until the portrait is painted\n  category      text, archetype text,\n  subject       text not null,                    -- what the painter is asked to photograph\n  personality   text, accessory text, background text, extra text,\n  bio           text not null default '',\n  lines         jsonb not null default '{}',      -- { win: [], big: [], lose: [], idle: [] }\n  price_cents   integer not null default 0 check (price_cents >= 0),\n  unlock_rounds integer check (unlock_rounds is null or unlock_rounds > 0),   -- Survivor rounds that unlock it\n  buyable       boolean not null default true,    -- false = unlock only\n  status        text not null default 'live' check (status in ('live', 'hidden')),\n  avatar_id     uuid references avatars(id) on delete set null,   -- the approved portrait\n  pending_id    uuid references avatars(id) on delete set null,   -- a new portrait waiting for approval\n  sort          integer not null default 0,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now()\n);\n\n-- who unlocked what by playing (for the \"unlocked!\" message and the books)\ncreate table if not exists legend_unlocks (\n  user_id    uuid not null references users(id) on delete cascade,\n  legend_id  text not null references legends(id) on delete cascade,\n  how        text not null default 'survivor',\n  seen       boolean not null default false,\n  created_at timestamptz not null default now(),\n  primary key (user_id, legend_id)\n);\n\n-- Survivor rounds played (settled seats), counted as they happen; backfilled from history\nalter table users add column if not exists survivor_rounds integer not null default 0;\nupdate users u set survivor_rounds = x.n from (\n  select s.user_id, count(*)::int n from pool_seats s join pool_rounds r on r.id = s.round_id\n   where r.status = 'settled' and s.user_id is not null group by s.user_id) x\n where x.user_id = u.id and u.survivor_rounds = 0;\n\ninsert into site_settings (key, value) values ('legends_unlocks_enabled', 'true') on conflict (key) do nothing;\n"
};
